    /// <summary>
    /// Tìm kiếm thông tin tài liệu nghiệp vụ theo operationId.
    /// </summary>
    public static bool TryGetOperation(string operationId, out CanonicalOperationMetadata metadata)
        => Operations.TryGetValue(operationId, out metadata!);

    /// <summary>
    /// Lấy mô tả tham số theo tên tham số và đường dẫn.
    /// </summary>
    public static string GetParameterDescription(string paramName, string? route = null)
    {
        if (ParameterDescriptions.TryGetValue(paramName, out var desc))
        {
            return desc;
        }
        return $"Giá trị tham số {paramName} được sử dụng trong yêu cầu.";
    }

    /// <summary>
    /// Lấy mô tả request body phù hợp với ngữ cảnh endpoint.
    /// </summary>
    public static string GetRequestBodyDescription(string operationId, string? fallback = null)
    {
        if (Operations.TryGetValue(operationId, out var meta) && !string.IsNullOrWhiteSpace(meta.RequestBodyDescription))
        {
            return meta.RequestBodyDescription;
        }
        return fallback ?? "Dữ liệu thông tin đầu vào của yêu cầu.";
    }

    /// <summary>
    /// Sinh mô tả mã trạng thái HTTP chuẩn xác dựa theo hành vi nghiệp vụ.
    /// </summary>
    public static string GetResponseDescription(string statusCode, string? summary = null)
    {
        var cleanSummary = string.IsNullOrWhiteSpace(summary) ? "Yêu cầu" : summary.TrimEnd('.');
        return statusCode switch
        {
            "200" => $"{cleanSummary} được xử lý thành công.",
            "201" => $"{cleanSummary} và tạo mới tài nguyên thành công.",
            "204" => $"{cleanSummary} hoàn tất thành công (không có dữ liệu trả về).",
            "400" => "Dữ liệu yêu cầu không hợp lệ hoặc vi phạm quy tắc nghiệp vụ.",
            "401" => "Yêu cầu cần được xác thực (chưa đăng nhập hoặc phiên làm việc đã hết hạn).",
            "403" => "Tài khoản không có quyền truy cập hoặc thực hiện thao tác nghiệp vụ này.",
            "404" => "Không tìm thấy tài nguyên theo thông tin định danh đã cung cấp.",
            "409" => "Yêu cầu xung đột với trạng thái hiện tại của tài nguyên trong hệ thống.",
            "500" => "Đã xảy ra lỗi nội bộ máy chủ khi xử lý yêu cầu.",
            _ => $"Phản hồi HTTP {statusCode}."
        };
    }
